import { cn } from "@/lib/utils";

// Matches http:// and https:// URLs only. Any other scheme (ftp, mailto,
// file, javascript, data, or a missing/misspelled scheme) is intentionally
// excluded so it never becomes an anchor.
const URL_REGEX = /https?:\/\/[^\s]+/g;

const ANCHOR_CLASS_NAME = "text-blue-600 underline break-all";

// Trailing punctuation and enclosing brackets are common in prose but are not
// part of the URL, so we peel them off the end of a raw match. Closing
// brackets are only stripped when the match has no matching opener, which lets
// URLs that legitimately contain balanced parentheses survive intact.
const trimTrailingPunctuation = (raw: string): string => {
  let url = raw;

  let keepTrimming = true;
  while (keepTrimming && url.length > 0) {
    const lastChar = url[url.length - 1];

    if (".,;:!?".includes(lastChar)) {
      url = url.slice(0, -1);
    } else if (lastChar === ")" && !url.includes("(")) {
      url = url.slice(0, -1);
    } else if (lastChar === "]" && !url.includes("[")) {
      url = url.slice(0, -1);
    } else {
      keepTrimming = false;
    }
  }

  return url;
};

const handleAnchorClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
  event.stopPropagation();
};

const linkifyString = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  const regex = new RegExp(URL_REGEX.source, "g");

  let lastIndex = 0;
  let keyIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(text)) !== null) {
    const url = trimTrailingPunctuation(match[0]);

    // Preserve the text (and any trimmed punctuation) that precedes the URL.
    const precedingEnd = match.index + url.length;
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }

    nodes.push(
      <a
        key={`link-${keyIndex++}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className={cn(ANCHOR_CLASS_NAME)}
        onClick={handleAnchorClick}
      >
        {url}
      </a>,
    );

    lastIndex = precedingEnd;
    // Advance the regex past the trimmed URL so trailing punctuation is
    // rendered as plain text rather than swallowed by the match.
    regex.lastIndex = precedingEnd;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const LinkifyText = ({
  children,
}: {
  children?: React.ReactNode;
}): JSX.Element => {
  if (typeof children === "string") {
    // Fast path: strings without an http(s) scheme are rendered verbatim so
    // the container's innerHTML matches the plain text exactly (no wrapper).
    if (!children.includes("http")) {
      return <>{children}</>;
    }

    return <>{linkifyString(children)}</>;
  }

  if (typeof children === "number") {
    return <>{String(children)}</>;
  }

  if (children === null || children === undefined) {
    return <></>;
  }

  return <>{children}</>;
};

export default LinkifyText;
